D=RADIUS*dir(31.586);
E=foot(A,B,C);
F=foot(D,B,C);
O=(0,0);

//Path Definitions
path quad= A -- B -- C -- D -- cycle;

//Initial Diagram
draw(Circle(O, RADIUS), linewidth(0.8));
draw(quad, linewidth(0.8));
label("$A$",A,W);
label("$B$",B,NW);
label("$C$",C,NE);
label("$D$",D,ENE);
label("$O$",O,S);
label("$\theta$",O,3N);

//Radii
draw(O--A);
draw(O--B);
draw(O--C);
draw(O--D);

//Construction
draw(A--E);
